function showVersion() {
  const pkgPath = path.join(PKG_ROOT, 'package.json');
  if (fs.existsSync(pkgPath)) {
    const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8'));
    console.log(`atomsystem v${pkg.version}`);
  } else {
    console.log('atomsystem v0.15.0');
  }
}

switch (command) {
  case 'init':
    handleInit();
    break;
  case 'refactor':
    handleRefactor();
    break;
  case 'skill':
    handleSkillInstall();
    break;
  case 'studio':
  case 'editor':
    handleStudio();
    break;
  case 'submit':
  case 'register':
    handleSubmit(targetName);
    break;
  case 'sync':
    handleSync();
    break;
  case 'schema':
    handleSchema();
    break;
  case 'build:tokens':
  case 'compile':
    handleBuildTokens();
    break;
  case 'add':
    handleAdd(targetName);
    break;
  case 'list':
    handleList();
    break;
  case 'version':
  case '-v':
  case '--version':
    showVersion();
    break;
  case 'help':
  case '-h':
  case '--help':
  default:
    showHelp();
    break;
}
